sys.path.insert(0,os.path.abspath('tmp/pdf-deps'))
import arabic_reshaper
from bidi.algorithm import get_display
from reportlab.pdfgen import canvas
from reportlab.lib.colors import HexColor, Color, white
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.lib.pagesizes import A4
os.makedirs('output/pdf',exist_ok=True)
pdfmetrics.registerFont(TTFont('Cairo','C:/Windows/Fonts/tahoma.ttf'))
pdfmetrics.registerFont(TTFont('CairoBold','C:/Windows/Fonts/tahomabd.ttf'))
W,H=A4; M=40; CW=W-2*M
navy='#14384E'; teal='#0798B7'; green='#16886D'; purple='#8256C7'; amber='#B97712'; gray='#526779'
C=canvas.Canvas('output/pdf/masal-handoff-guide.pdf',pagesize=A4)
C.setTitle('ماسال - دليل التشغيل والتسليم'); C.setAuthor('ماسال | عراق تكنو')
page_num=0

def ar(s):return get_display(arabic_reshaper.reshape(str(s)))
def line(s,x,y,size=11,color=navy,bold=False):
 C.setFillColor(HexColor(color));C.setFont('CairoBold' if bold else 'Cairo',size);C.drawRightString(x,y,ar(s))
def wrap(s,width,size=11,bold=False):
 words=s.split();out=[];cur='';font='CairoBold' if bold else 'Cairo'
 for word in words:
  trial=(cur+' '+word).strip()
  if cur and pdfmetrics.stringWidth(ar(trial),font,size)>width:out.append(cur);cur=word
  else:cur=trial
 if cur:out.append(cur)
 return out

def para(s,y,width=CW,x=None,size=11,color=gray,leading=20,bold=False):
 x=W-M if x is None else x
 for text in wrap(s,width,size,bold):line(text,x,y,size,color,bold);y-=leading
 return y

def start(title,tag='دليل التشغيل'):
 global page_num
 page_num+=1
 C.setFillColor(HexColor('#F5F8FB'));C.rect(0,0,W,H,fill=1,stroke=0)
 C.setFillColor(HexColor(navy));C.rect(0,H-114,W,114,fill=1,stroke=0)
 line('ماسال  /  '+tag,W-M,H-38,10,'#7DDAE6',True)
 line(title,W-M,H-77,24,'#FFFFFF',True)
 C.setStrokeColor(HexColor('#D9E4EB'));C.line(M,44,W-M,44)
 line('نسخة المحاكاة المحلية | 24 سبتمبر 2026',W-M,26,9,gray)
 C.setFont('Helvetica',10);C.setFillColor(HexColor(teal));C.drawString(M,27,f'{page_num:02d}')
 return H-145

def end():C.showPage()
def card(title,body,y,color=teal):
 lines=[]
 for item in body:lines.extend(wrap(item,CW-36,11));lines.append(None)
 if lines and lines[-1] is None:lines.pop()
 height=44+sum(8 if a is None else 19 for a in lines)+14
 if y-height<62:raise Exception('Page overflow '+title+' '+str(y-height))
 C.setFillColor(white);C.setStrokeColor(HexColor('#DAE5EB'));C.roundRect(M,y-height,CW,height,12,fill=1,stroke=1)
 C.setFillColor(HexColor(color));C.roundRect(W-M-5,y-height+13,4,height-26,2,fill=1,stroke=0)
 line(title,W-M-18,y-26,14,color,True)
 yy=y-51
 for text in lines:
  if text is None:yy-=8
  else:line(text,W-M-18,yy,11,gray);yy-=19
 return y-height-15

def table(rows,y,widths=(155,CW-155)):
 for i,(a,b) in enumerate(rows):
  left=wrap(b,widths[1]-24,10.5);right=wrap(a,widths[0]-22,10.5,True)
  h=max(len(left),len(right))*18+20
  if y-h<60:raise Exception('table overflow')
  C.setFillColor(HexColor('#FFFFFF' if i%2==0 else '#EDF4F7'));C.roundRect(M,y-h,CW,h,5,fill=1,stroke=0)
  for n,t in enumerate(right):line(t,W-M-12,y-20-n*18,10.5,navy,True)
  for n,t in enumerate(left):line(t,W-M-widths[0]-12,y-20-n*18,10.5,gray)
  y-=h+3
 return y-14

def flow(items,y):
 for i,(title,desc) in enumerate(items):
  h=68;C.setFillColor(HexColor(['#E8F5F8','#E9F5F1','#F1ECFA','#FBF3E8'][i%4]));C.roundRect(M,y-h,CW,h,10,fill=1,stroke=0)
  line(str(i+1)+'  '+title,W-M-16,y-25,13,navy,True);line(desc,W-M-16,y-49,10.5,gray)
  y-=h+20
  if i<len(items)-1:
   C.setStrokeColor(HexColor(teal));C.line(W/2,y+17,W/2,y+4);C.line(W/2,y+4,W/2-4,y+9);C.line(W/2,y+4,W/2+4,y+9)
 return y

